    def __init__(self, value):
        self.value = value


class TimesTwo(BaseClass):
    def __init__(self, value):
        super().__init__(value)
        self.value *= 2


class PlusFive(BaseClass):
    def __init__(self, value):
        super().__init__(value)
        self.value += 5


class ThisWay(TimesTwo, PlusFive):
    def __init__(self, value):
        super().__init__(value)


mro_str = "\n".join(repr(cls) for cls in ThisWay.__mro__)
print(mro_str)

&lt;class '__main__.ThisWay'&gt;
&lt;class '__main__.TimesTwo'&gt;
&lt;class '__main__.PlusFive'&gt;
&lt;class '__main__.BaseClass'&gt;
&lt;class 'object'&gt;



Here the ordering is

\[
\begin{align}
\text{ThisWay} \rightarrow \text{TimesTwo} \rightarrow \text{PlusFive} \rightarrow \text{BaseClass} \rightarrow \text{object}
\end{align}
\]

Means that the __init__ methods work backwards from the definition order

Since we walk up the chain calling __init__ recursively, then return back

BaseClass sets value to \(5\)
PlusFive then adds \(5\) to get \(10\)
TimesTwo then multiplies by \(2\) to get \(20\)
ThisWay doesn’t then change the value


super is also more flexible and maintainable

If we rename the class we don’t have to change the super call
Can also be called with two parameters

Type of the class who MRO parent view you’re trying to access
The instance on which to access that view

Parameters are not required but will be supplied automatically (__class__ and self) when they are not passed
The following are equivalent



class BaseClass:
    def __init__(self, value):
        self.value = value

class ExplicitTrisect(BaseClass):
    def __init__(self, value):
        super(ExplicitTrisect, self).__init__(value)
        self.value /= 3

class AutomaticTrisect(BaseClass):
    def __init__(self, value):
        super(__class__, self).__init__(value)
        self.value /= 3

class ImplicitTrisect(BaseClass):
    def __init__(self, value):
        super().__init__(value)
        self.value /= 3

assert ExplicitTrisect(9).value == 3
assert AutomaticTrisect(9).value == 3
assert ImplicitTrisect(9).value == 3


